import React, { useEffect, useState, useRef  } from "react";
import query from "jquery";
import { Link, NavLink, useNavigate  } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import axios from "axios";
import { toast,ToastContainer  } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import HeaderLocation from "./HeaderLocation";


const HeaderOne = ({ onRecommendedClick, onBrandsClick }) => {
    const { data: subcategorydata, isLoading:subdataloding } = useQuery({
      queryKey: ["subcategorydatakey"],
      queryFn: async () => {
        const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/subcategory`);
        return response.data;
      },
    });

  const [scroll, setScroll] = useState(false);
  useEffect(() => {
    window.onscroll = () => {
      if (window.pageYOffset < 150) {
        setScroll(false);
      } else if (window.pageYOffset > 150) {
        setScroll(true);
      }
      return () => (window.onscroll = null);
    };
    const selectElement = query(".js-example-basic-single");
    selectElement.select2();

    return () => {
      if (selectElement.data("select2")) {
        selectElement.select2("destroy");
      }
    };
  }, []);

  // Set the default language
  const [selectedLanguage, setSelectedLanguage] = useState("Eng");
  const handleLanguageChange = (language) => {
    setSelectedLanguage(language);
  };

  // Set the default currency
  const [selectedCurrency, setSelectedCurrency] = useState("Rupee");
  const handleCurrencyChange = (currency) => {
    setSelectedCurrency(currency);
  };

  // Mobile menu support
  const [menuActive, setMenuActive] = useState(false);
  const [activeIndex, setActiveIndex] = useState(null);
  const handleMenuClick = (index) => {
    setActiveIndex(activeIndex === index ? null : index);
  };
  const handleMenuToggle = () => {
    setMenuActive(!menuActive);
  };

  // Search control support
  const [activeSearch, setActiveSearch] = useState(false);
  const handleSearchToggle = () => {
    setActiveSearch(!activeSearch);
  };

  // category control support
  const dropdownRef = useRef(null);
  const [activeCategory, setActiveCategory] = useState(false);

  // Toggle dropdown
  const handleCategoryToggle = () => {
    setActiveCategory((prev) => !prev);
  };

  // Navigate and close dropdown
  const handleCategoryNavigate = (categoryId) => {
    setActiveCategory(false);
    if (categoryId === "all") navigate("/shop");
    else navigate(`/shop/${categoryId}`);
  };

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setActiveCategory(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // user 
  const navigate = useNavigate();
  const [user, setUser] = useState(null);

  useEffect(() => {
    // check if user info exists in localStorage
    const storedUser = localStorage.getItem("user");
    if (storedUser) setUser(JSON.parse(storedUser));
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("user");
    localStorage.removeItem("token");
    setUser(null);
    navigate("/account"); // redirect to login/register page
  };

 //update cart count 
 const [cartCount, setCartCount] = useState(0);

 // Update cart count whenever localStorage changes
 useEffect(() => {
   const updateCartCount = () => {
     const cart = localStorage.getItem("cart")
       ? JSON.parse(localStorage.getItem("cart"))
       : [];
     const totalItems = cart.reduce((sum, item) => sum + (Number(item.quantity) || 0), 0);
     setCartCount(totalItems);
   };

   updateCartCount();

   // Optional: listen for storage events if cart can change in another tab
   window.addEventListener("storage", updateCartCount);
   return () => window.removeEventListener("storage", updateCartCount);
 }, []);

 // update wishlist count — mirrors the cart count pattern above, reading
 // the same "wishlist" localStorage key that ProductListOne.jsx,
 // ProductPage.jsx and WishListSection.jsx all read/write.
 const [wishlistCount, setWishlistCount] = useState(0);

 useEffect(() => {
   const updateWishlistCount = () => {
     const wishlist = JSON.parse(localStorage.getItem("wishlist")) || [];
     setWishlistCount(wishlist.length);
   };

   updateWishlistCount();

   window.addEventListener("storage", updateWishlistCount);
   return () => window.removeEventListener("storage", updateWishlistCount);
 }, []);


  //category header 

  const { data: categorydata, isLoading } = useQuery({
    queryKey: ["categorydata"],
    queryFn: async () => {
      const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/admindata/getCategory`);
      return res.data;
    },
  });

  const handleChange = (e) => {
    const selectedId = e.target.value;
      if (selectedId && selectedId !== "all") {
        navigate(`/shop/${selectedId}`);
      } else {
        navigate("/shop"); // or stay on same page
      }
    };



    // Fetch orders 
    const [orders, setOrders] = useState([]);
    const storedUser = localStorage.getItem("user");
    const username = storedUser ? JSON.parse(storedUser).username : null;
    const token = localStorage.getItem("token");


  useEffect(() => {
    const fetchOrders = async () => {
      try {
        const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/order/user/${username}`, {
          headers: { Authorization: `Bearer ${token}` },
        });

        if (res.data.success && Array.isArray(res.data.orders)) {
          const groupedOrders = res.data.orders.reduce((acc, order) => {
            const existing = acc.find((o) => o._id === order._id);
            if (existing) {
              existing.products.push(...order.products);
            } else {
              acc.push({ ...order, products: [...order.products] });
            }
            return acc;
          }, []);

          setOrders(groupedOrders);
        } else {
          toast.info(res.data.message || "No orders found");
        }
      } catch (err) {
        console.error("Error fetching orders:", err);
        toast.error("Failed to load orders");
      }
    };

    fetchOrders();
  }, [username, token]);


  // cart section count  
  const [cartCount1, setCartCount1] = useState(0);

  useEffect(() => {
    const storedCart = JSON.parse(localStorage.getItem("cart")) || [];
    const count = storedCart.reduce((sum, item) => sum + (Number(item.quantity) || 0), 0);
    setCartCount1(count);
  }, []);


  // search bar 
  const [searchText, setSearchText] = useState("");

  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      const query = searchText.trim();
      if (query) {
        navigate(`/shop?product=${encodeURIComponent(query)}`);
      } else {
        navigate("/shop");
      }
    }
  };

  // ==================== Search Suggestions Start ====================
  const [suggestions, setSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [suggestionsLoading, setSuggestionsLoading] = useState(false);
  const searchWrapperRef = useRef(null);

  // Escape regex special characters so user input can't break the query
  const escapeRegex = (str) => str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

  // Fetch suggestions whenever searchText changes (debounced)
  useEffect(() => {
    const fetchSuggestions = async () => {
      if (!searchText.trim()) {
        setSuggestions([]);
        setShowSuggestions(false);
        return;
      }
      try {
        setSuggestionsLoading(true);
        const escaped = escapeRegex(searchText.trim());
        const res = await axios.get(
          `${process.env.REACT_APP_API_URL}/api/product/search`,
          { params: { name: `^${escaped}` } }
        );
        if (res.data.success) {
          setSuggestions(res.data.products.slice(0, 8));
        } else {
          setSuggestions([]);
        }
        setShowSuggestions(true);
      } catch (err) {
        console.error("Error fetching suggestions:", err);
        setSuggestions([]);
      } finally {
        setSuggestionsLoading(false);
      }
    };
    const debounce = setTimeout(fetchSuggestions, 250);
    return () => clearTimeout(debounce);
  }, [searchText]);

  // Close suggestions when clicking outside
  useEffect(() => {
    const handleClickOutsideSearch = (event) => {
      if (searchWrapperRef.current && !searchWrapperRef.current.contains(event.target)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutsideSearch);
    return () => document.removeEventListener("mousedown", handleClickOutsideSearch);
  }, []);

  const handleSuggestionClick = (product) => {
    setSearchText(product.name);
    setShowSuggestions(false);
    navigate(`/shop?product=${encodeURIComponent(product.name)}`);
  };
  // ==================== Search Suggestions End ====================

  return (
    <>
      <div className='overlay' />
      <div
        className={`side-overlay ${(menuActive || activeCategory) && "show"}`}
      />
      {/* ==================== Search Box Start Here ==================== */}
      <form action='#' className={`search-box ${activeSearch && "active"}`}>
        <button
          onClick={handleSearchToggle}
          type='button'
          className='search-box__close position-absolute inset-block-start-0 inset-inline-end-0 m-16 w-48 h-48 border border-gray-100 rounded-circle flex-center text-white hover-text-gray-800 hover-bg-white text-2xl transition-1'
        >
          <i className='ph ph-x' />
        </button>
        <div className='container'>
          <div className='position-relative'>
            <input
              type='text'
              className='form-control py-16 px-24 text-xl rounded-pill pe-64'
              placeholder='Search for a product or brands'
            />
            <button
              type='submit'
              className='w-48 h-48 bg-main-600 rounded-circle flex-center text-xl text-white position-absolute top-50 translate-middle-y inset-inline-end-0 me-8'
            >
              <i className='ph ph-magnifying-glass' />
            </button>
          </div>
        </div>
      </form>
      {/* ==================== Search Box End Here ==================== */}
      {/* ==================== Mobile Menu Start Here ==================== */}
      <div
        className={`mobile-menu scroll-sm d-lg-none d-block ${
          menuActive && "active"
        }`}
      >
        <button
          onClick={() => {
            handleMenuToggle();
            setActiveIndex(null);
          }}
          type='button'
          className='close-button'
        >
          <i className='ph ph-x' />{" "}
        </button>
        <div className='mobile-menu__inner'>
          <Link to='/' className='mobile-menu__logo'>
            <img src='../../assets/images/logo/logo.png' alt='Logo' />
          </Link>
          <div className='mobile-menu__menu' >
            {/* Nav Menu Start */}
            <ul className='nav-menu flex-align nav-menu--mobile'>
              {/* Home Menu */}
              <li
                onClick={() => handleMenuClick(0)}
                className={`on-hover-item nav-menu__item has-submenu ${
                  activeIndex === 0 ? "d-block" : ""
                }`}
              >
                <Link to='/' className='nav-menu__link'>
                  Home
                </Link>
              </li>

              {/* Shop Menu */}
              <li
                onClick={() => handleMenuClick(1)}
                className={`on-hover-item nav-menu__item has-submenu ${
                  activeIndex === 1 ? "d-block" : ""
                }`}
              >
                <Link to='/brand' className='nav-menu__link'>
                  Brand
                </Link>
              </li>
              {/* Contact Us Menu */}
              <li className='nav-menu__item'>
                <Link
                  to='/products'
                  className='nav-menu__link'
                  onClick={() => setActiveIndex(null)}
                >
                  All products
                </Link>
              </li>

              {/* Contact Us Menu */}
              <li className='nav-menu__item'>
                <Link
                  to='/contact'
                  className='nav-menu__link'
                  onClick={() => setActiveIndex(null)}
                >
                  Contact Us
                </Link>
              </li>
              <li className='nav-menu__item'>
                <Link
                  to='/seller'
                  className='nav-menu__link'
                  onClick={() => setActiveIndex(null)}
                >
                  Become a Seller
                </Link>
              </li>
              <li className='nav-menu__item'>
                <Link
                  to='/admin'
                  className='nav-menu__link'
                  onClick={() => setActiveIndex(null)}
                >
                  Admin
                </Link>
              </li>
              {/*  Delivery Boy - Mobile Menu */}
              <li className='nav-menu__item'>
                <Link
                  to='/delivery/login'
                  className='nav-menu__link'
                  onClick={() => setActiveIndex(null)}
                >
                  Delivery Boy Panel
                </Link>
              </li>
            </ul>
            {/* Nav Menu End */}
          </div>
        </div>
      </div>
      {/* ==================== Mobile Menu End Here ==================== */}
      {/* ======================= Middle Top Start ========================= */}
      <div className='header-top flex-between' style={{ backgroundColor: "#558B2F", borderBottom: "1px solid #fff" }}>
        <div className='container container-lg'>
          <div className='flex-between flex-wrap gap-8'>
            <ul className='flex-align flex-wrap d-none d-md-flex'>
              <li className='border-right-item'>
                <Link
                  to='/seller'
                  className='text-white text-sm hover-text-decoration-underline'
                >
                  <b>Become A Seller</b>
                </Link>
              </li>
              <li className='border-right-item'>
                <Link
                  to='/admin'
                  className='text-white text-sm hover-text-decoration-underline'
                >
                  <b>Admin</b>
                </Link>
              </li>
              {/* ✅ Delivery Boy - Top Bar */}
              <li className='border-right-item'>
                <Link
                  to='/delivery/login'
                  className='text-white text-sm hover-text-decoration-underline'
                >
                  <b>Delivery Boy</b>
                </Link>
              </li>
              <li>
                <HeaderLocation />
              </li>
            </ul>
            <ul className='header-top__right flex-align flex-wrap'>
              <li className='on-hover-item border-right-item border-right-item-sm-space has-submenu arrow-white'>
                <Link to='#' className='text-white text-sm py-8'>
                  <b>Help Center</b>
                </Link>
                <ul className='on-hover-dropdown common-dropdown common-dropdown--sm max-h-200 scroll-sm px-0 py-8'>
                  <li className='nav-submenu__item'>
                    <Link
                      to='/contact'
                      className='nav-submenu__link hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                    >
                      <span className='text-sm d-flex'>
                        <i className='ph ph-headset' />
                      </span>
                     <b>Contact</b>
                    </Link>
                  </li>
                </ul>
              </li>
              <li className='on-hover-item border-right-item border-right-item-sm-space has-submenu arrow-white'>
                {/* Display the selected language here */}
                <Link to='#' className='selected-text text-white text-sm py-8'>
                  <b>{selectedLanguage}</b>
                </Link>
                <ul className='selectable-text-list on-hover-dropdown common-dropdown common-dropdown--sm max-h-200 scroll-sm px-0 py-8'>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleLanguageChange("India")}
                    >
                      <img
                        src='assets/images/thumbs/flag1.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      <b>India</b>
                    </Link>
                  </li>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleLanguageChange("Japan")}
                    >
                      <img
                        src='assets/images/thumbs/flag2.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      Japan
                    </Link>
                  </li>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleLanguageChange("French")}
                    >
                      <img
                        src='assets/images/thumbs/flag3.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      French
                    </Link>
                  </li>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleLanguageChange("Germany")}
                    >
                      <img
                        src='assets/images/thumbs/flag4.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      Germany
                    </Link>
                  </li>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleLanguageChange("Bangladesh")}
                    >
                      <img
                        src='assets/images/thumbs/flag6.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      Bangladesh
                    </Link>
                  </li>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleLanguageChange("South Korea")}
                    >
                      <img
                        src='assets/images/thumbs/flag5.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      South Korea
                    </Link>
                  </li>
                </ul>
              </li>
              <li className='on-hover-item border-right-item border-right-item-sm-space has-submenu arrow-white'>
                {/* Display the selected currency */}
                <Link to='#' className='selected-text text-white text-sm py-8'>
                  <b>{selectedCurrency}</b>
                </Link>
                <ul className='selectable-text-list on-hover-dropdown common-dropdown common-dropdown--sm max-h-200 scroll-sm px-0 py-8'>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleCurrencyChange("Rupee")}
                    >
                      <img
                        src='assets/images/thumbs/flag1.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      <b>Rupee</b>
                    </Link>
                  </li>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleCurrencyChange("Yen")}
                    >
                      <img
                        src='assets/images/thumbs/flag2.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      Yen
                    </Link>
                  </li>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleCurrencyChange("Franc")}
                    >
                      <img
                        src='assets/images/thumbs/flag3.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      Franc
                    </Link>
                  </li>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleCurrencyChange("EURO")}
                    >
                      <img
                        src='assets/images/thumbs/flag4.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      EURO
                    </Link>
                  </li>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleCurrencyChange("BDT")}
                    >
                      <img
                        src='assets/images/thumbs/flag6.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      BDT
                    </Link>
                  </li>
                  <li>
                    <Link
                      to='#'
                      className='hover-bg-gray-100 text-gray-500 text-xs py-6 px-16 flex-align gap-8 rounded-0'
                      onClick={() => handleCurrencyChange("WON")}
                    >
                      <img
                        src='assets/images/thumbs/flag5.png'
                        alt=''
                        className='w-16 h-12 rounded-4 border border-gray-100'
                      />
                      WON
                    </Link>
                  </li>
                </ul>
              </li>
              <ul className="nav-list d-flex">
                <li className="border-right-item">
                  {user ? (
                    <div className="flex-align gap-6 cursor-pointer">
                      <span className="icon text-md d-flex">
                        <i className="ph ph-user-circle text-white" />
                      </span>
                      <span className="text-white">
                      <b>{user.firstName}</b>

                      </span>
                      <button
                        onClick={handleLogout}
                        className="btn btn-sm ms-16" style={{backgroundColor: 'rgb(255, 167, 38)'}}
                      >
                        Logout
                      </button>
                    </div>
                  ) : (
                    <Link
                      to="/account"
                      className="text-white text-sm py-8 flex-align gap-6"
                    >
                      <span className="icon text-md d-flex">
                        <i className="ph ph-user-circle" />
                      </span>
                      <span className="hover-text-decoration-underline">
                        <b>{user?.firstName || "My Account"}</b>
                      </span>

                    </Link>
                  )}
                </li>
                {/* other menu items */}
              </ul>
            </ul>
          </div>
        </div>
      </div>
      {/* ======================= Middle Top End ========================= */}
      {/* ======================= Middle Header Start ========================= */}
      <header className="header-middle border-b border-gray-200 p-0" style={{ backgroundColor: "#1B5E20" }}>
        <div className='container container-lg '>
          <nav className='header-inner flex-between'>
            {/* Logo Start */}
            <div className='logo' style={{ display: 'flex', alignItems: 'center', gap: '30px' }}>
                  <Link to='/' className='link'>
                    <img src='../../assets/images/logo/logo.png' alt='Logo' width='80'/>
                  </Link>
                  <h5 className="text-white fw-bold p-0 m-0">Online Multi Vendor Store</h5>
                </div>
            {/* Logo End  */}
            {/* form location Start */}
            <form
              action='#'
              className='flex-align flex-wrap form-location-wrapper'
            >
              {/* ==================== Search + Category Start ==================== */}
              <div className="search-category bg-white d-flex h-48 search-form d-sm-flex d-none rounded-full shadow-sm" style={{borderRadius:'9999px'}}>
                  <select
                    defaultValue="all"
                    className="form-select fw-bold border-end-0"
                    onChange={handleChange}
                    style={{ maxWidth: '160px', minWidth: '100px' }}
                  >
                  <option value="all">All Categories</option>
                    {!isLoading &&
                      categorydata?.length > 0 &&
                      categorydata.map((cat) => (
                        <option key={cat._id} value={cat._id}>
                          {cat.name}
                        </option>
                      ))}
                </select>
                <div className="search-form__wrapper position-relative" ref={searchWrapperRef}>
                <input
                  type="text"
                  value={searchText}
                  onChange={(e) => setSearchText(e.target.value)}
                  onKeyDown={handleKeyDown}
                  onFocus={() => searchText && setShowSuggestions(true)}
                  className="search-form__input common-input py-13 ps-16 pe-18 rounded-end-pill pe-44 bg-white border border-black"
                  placeholder="Search products..."
                  autoComplete="off"
                />
                <button
                  type="button"
                  onClick={() => {
                    const query = searchText.trim();
                    if (query) navigate(`/shop?product=${encodeURIComponent(query)}`);
                    else navigate("/shop");
                  }}
                  className="w-32 h-32 bg-main-600 rounded-circle flex-center text-xl text-white position-absolute top-50 translate-middle-y inset-inline-end-0 me-8"
                >
                  <i className="ph ph-magnifying-glass" />
                </button>

                {/* Suggestions dropdown */}
                {showSuggestions && searchText.trim() && (
                  <ul
                    className="scroll-sm"
                    style={{
                      position: "absolute",
                      top: "110%",
                      left: 0,
                      width: "100%",
                      background: "#fff",
                      border: "1px solid #eee",
                      borderRadius: "8px",
                      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
                      listStyle: "none",
                      padding: "8px 0",
                      margin: 0,
                      maxHeight: "320px",
                      overflowY: "auto",
                      zIndex: 1000,
                    }}
                  >
                    {suggestionsLoading && (
                      <li className="px-16 py-8 text-gray-500 text-sm">Searching...</li>
                    )}
                    {!suggestionsLoading && suggestions.length === 0 && (
                      <li className="px-16 py-8 text-gray-500 text-sm">No products found</li>
                    )}
                    {!suggestionsLoading &&
                      suggestions.map((product) => (
                        <li
                          key={product._id}
                          onClick={() => handleSuggestionClick(product)}
                          className="flex-align gap-8 px-16 py-8 hover-bg-gray-100"
                          style={{ cursor: "pointer" }}
                        >
                          {product.image && (
                            <img
                              src={product.image}
                              alt={product.name}
                              width="32"
                              height="32"
                              style={{ objectFit: "cover", borderRadius: "4px" }}
                            />
                          )}
                          <span className="text-sm text-gray-800">{product.name}</span>
                        </li>
                      ))}
                  </ul>
                )}
              </div>
              </div>
              {/* ==================== Search + Category End ==================== */}
            </form>
            {/* Header Middle Right start */}
            <div className='header-right flex-align d-lg-block d-none'>
              <div className='flex-align flex-wrap gap-12'>
                <button
                  type='button'
                  className='search-icon flex-align d-lg-none d-flex gap-3 item-hover'
                >
                  <span className='text-2xl text-gray-700 d-flex position-relative item-hover__text'>
                    <i className='ph ph-magnifying-glass' />
                  </span>
                </button>
                {user ? (
                    <Link to='/myorders' className='flex-align gap-4 item-hover'>
                      <span className='text-2xl text-gray-700 d-flex position-relative me-6 mt-6 item-hover__text'>
                      <b>
                          <i className='ph ph-package text-white' />
                        <span className='w-16 h-16 flex-center rounded-circle bg-main-600 text-white text-xs position-absolute top-n6 end-n4'>
                           {orders.length} {/* Total orders */}
                        </span>
                      </b>
                      </span>
                      <span className='text-md text-white item-hover__text-white d-lg-flex'>
                        <b>my Orders</b>
                      </span>
                    </Link>
                  ) : (
                    <>
                    </>
                  )}
                {/* Wishlist — restored as its own link. This used to share the
                    heart icon with "My Orders" above (which had been
                    repointed to /myorders at some point), so the wishlist
                    itself had no working nav entry. This is separate and
                    reads the live wishlist count from localStorage. */}
                <Link to='/wishlist' className='flex-align gap-4 item-hover'>
                  <span className='text-2xl text-gray-700 d-flex position-relative me-6 mt-6 item-hover__text'>
                    <b>
                      <i className='ph ph-heart text-white' />
                      <span className='w-16 h-16 flex-center rounded-circle bg-main-600 text-white text-xs position-absolute top-n6 end-n4'>
                        {wishlistCount}
                      </span>
                    </b>
                  </span>
                  <span className='text-md text-white item-hover__text-white d-lg-flex'>
                    <b>Wishlist</b>
                  </span>
                </Link>
                <Link to='/cart' className='flex-align gap-4 item-hover'>
                  <span className='text-2xl text-gray-700 d-flex position-relative me-6 mt-6 item-hover__text'>
                    <b>                    <i className='ph ph-shopping-cart-simple text-white text-2xl'  />
                      <span className="w-16 h-16 flex-center rounded-circle bg-main-600 text-white text-xs position-absolute top-n6 end-n4">
                        {cartCount1}
                      </span>
                    </b>

                  </span>
                    <b>                  <span className='text-md text-white item-hover__text-white d-lg-flex'>
                    Cart
                  </span></b>
                </Link>
              </div>
            </div>
            {/* Header Middle Right End  */}
          </nav>
        </div>
      </header>
      {/* ======================= Middle Header End ========================= */}
      {/* ==================== Header Start Here ==================== */}
      <header
        className={`header bg-white border-bottom border-gray-100 ${
          scroll && "fixed-header"
        }`}
      >
        <div className=''>
          <nav className='header-inner d-flex justify-content-between gap-8' style={{backgroundColor: '#4CAF50'}}>
            <div className='flex-align menu-category-wrapper'>
              {/* Category Dropdown Start */}
              <div className="category on-hover-item position-relative" ref={dropdownRef}>
                {/* Main button */}
                <button
                  onClick={handleCategoryToggle}
                  type="button"
                  className="category__button flex-align gap-8 fw-medium p-16 border-end border-start border-gray-100 text-heading"
                >
                  <span className="icon text-2xl d-xs-flex d-none">
                    <i className="ph ph-dots-nine" />
                  </span>
                  <span className="d-sm-flex d-none"style={{ color: '#ffffff' }}>All Categories</span>
                  <span className="arrow-icon text-xl d-flex ">
                    <i className={`ph ${activeCategory ? "ph-caret-up" : "ph-caret-down"}`} />
                  </span>
                </button>

                {/* Dropdown list */}
                {activeCategory && (
                  <div className="responsive-dropdown cat common-dropdown nav-submenu p-0 submenus-submenu-wrapper active">
                    <ul className="scroll-sm p-0 py-8 w-300 max-h-400 overflow-y-auto">
                      {isLoading && (
                        <li className="px-16 py-12 text-gray-500">Loading categories...</li>
                      )}

                      {/* Dynamic categories */}
                      {!isLoading &&
                        categorydata?.length > 0 &&
                        categorydata.map((cat) => (
                          <li key={cat._id}>
                            <button
                              type="button"
                              className="dropdown-link px-16 py-8 text-start w-100"
                              onClick={() => handleCategoryNavigate(cat._id)}
                            >
                              {cat.name}
                            </button>
                          </li>
                        ))}
                    </ul>
                  </div>
                )}
              </div>
              {/* Category Dropdown End  */}
              {/* Menu Start  */}
              <div className='header-menu d-lg-block d-none '>
                {/* Nav Menu Start */}
                <ul className='nav-menu flex-align '>
                  <li className='on-hover-item  '>
                    <Link to='/' className='nav-menu__link'style={{ color: '#ffffff' }}>
                      Home
                    </Link>
                  </li>
                  <li className='on-hover-item'>
                    <Link to='/Brand' className='nav-menu__link'style={{ color: '#ffffff' }}>
                      Brand
                    </Link>
                  </li>
                  <li className='on-hover-item nav-menu__item has-submenu'>
                    <Link to='#' className='nav-menu__link' style={{ color: '#ffffff' }}>
                      Subcategory
                    </Link>
                    <ul className='on-hover-dropdown common-dropdown nav-submenu scroll-sm'>
                      <li className='common-dropdown__item nav-submenu__item'>
                        {!subdataloding && subcategorydata?.length > 0 &&
                          subcategorydata.map((subcat) => (
                            <NavLink 
                              key={subcat._id}
                              to={`/subcategory/${subcat._id}`}
                              className={(navData) => 
                                navData.isActive
                                  ? "common-dropdown__link nav-submenu__link hover-bg-neutral-100 activePage"
                                  : "common-dropdown__link nav-submenu__link hover-bg-neutral-100"
                              } 
                            >
                              {subcat.name}
                            </NavLink>
                          ))}
                      </li>
                    </ul>
                  </li>
                  <li className='nav-menu__item'>
                    <NavLink
                      to='/products'
                      className={(navData) =>
                        navData.isActive
                          ? "nav-menu__link activePage"
                          : "nav-menu__link"
                      }
                    style={{ color: '#ffffff' }}>
                      All Products
                    </NavLink>
                  </li>
                  <li className='nav-menu__item'>
                    <NavLink
                      to='/contact'
                      className={(navData) =>
                        navData.isActive
                          ? "nav-menu__link activePage"
                          : "nav-menu__link"
                      }
                    style={{ color: '#ffffff' }}>
                      Contact Us
                    </NavLink>
                  </li>
                </ul>
                {/* Nav Menu End */}
              </div>
              {/* Menu End  */}
            </div>
            {/* Header Right start */}
            <div className='header-right flex-align'>
              <div className='me-16 d-lg-none d-block'>
                <div className='flex-align flex-wrap gap-12'>
                  <button
                    onClick={handleSearchToggle}
                    type='button'
                    className='search-icon flex-align d-lg-none d-flex gap-4 item-hover'
                  >
                    <span className='text-2xl text-gray-700 d-flex position-relative item-hover__text'>
                      <i className='ph ph-magnifying-glass' />
                    </span>
                  </button>
                  <Link to='/cart' className='flex-align gap-4 item-hover'>
                    <span className='text-2xl text-gray-700 d-flex position-relative me-6 mt-6 item-hover__text'>
                      <i className='ph ph-shopping-cart-simple' />
                      <span className='w-16 h-16 flex-center rounded-circle bg-main-600 text-white text-xs position-absolute top-n6 end-n4'>
                        2
                      </span>
                    </span>
                    <span className='text-md text-gray-500 item-hover__text d-none d-lg-flex'>
                      Cart
                    </span>
                  </Link>
                </div>
              </div>
              <button
                onClick={handleMenuToggle}
                type='button'
                className='toggle-mobileMenu d-lg-none ms-3n text-gray-800 text-4xl d-flex'
              >
                {" "}
                <i className='ph ph-list' />{" "}
              </button>
            </div>
            {/* Header Right End  */}
          </nav>
        </div>
      </header>
      {/* ==================== Header End Here ==================== */}
    </>
  );
};

export default HeaderOne;